import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../../types/session.js';
import type {SessionStore} from '../../types/sessionStore.js';
import {setLogger} from '../../shared/logger.js';

describe('list_sessions error logging', () => {
  const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];

  beforeEach(() => {
    logLines.length = 0;
    const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
      void logLines.push({level, category, message, fields});
    setLogger({
      debug: record('debug'),
      info: record('info'),
      warn: record('warn'),
      error: record('error'),
    });
  });

  afterEach(() => {
    setLogger();
  });

  it('logs the session id and user id on listFor failure without leaking user content', async () => {
    const store: SessionStore = {
      listFor: () => Promise.reject(new Error('database offline')),
    } as unknown as SessionStore;

    const ws = {
      readyState: WebSocket.OPEN,
      send: jest.fn(),
    } as unknown as WebSocket;

    const orchestrator = {} as ChatOrchestrator;
    const session: ChatSession = {sessionId: 's-error-1', userId: 'u1', entries: []};

    const handle = createMessageHandler(orchestrator, store, {enabled: true});

    await handle(ws, session, {type: 'list_sessions'});

    const errorLogs = logLines.filter(line => line.level === 'error' && line.category === 'ws');
    expect(errorLogs).toHaveLength(1);
    expect(errorLogs[0].fields).toEqual(expect.objectContaining({
      sessionId: 's-error-1',
      userId: 'u1',
      error: 'database offline',
    }));
  });
});

